sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?husband ?husbandName ?birthPlace ?birthPlaceLabel WHERE {
  {
    <http://dbpedia.org/resource/Atang_de_la_Rama> dbo:spouse ?husband .
  } UNION {
    <http://dbpedia.org/resource/Atang_de_la_Rama> dbp:spouse ?husband .
  }
  OPTIONAL { ?husband rdfs:label ?husbandName FILTER (lang(?husbandName) = "en") }
  OPTIONAL {
    ?husband dbo:birthPlace ?birthPlace .
    OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER (lang(?birthPlaceLabel) = "en") }
  }
}
LIMIT 100

